para:
/* "Ligado agora": nome abre a divisão; botões apagam luzes / desligam AC */
.onm {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 78px;
  padding: 6px 0;
  font-weight: 600;
  font-size: 13px;
  text-align: left;
}
.onm small {
  color: var(--mute);
  font-size: 15px;
}
.onrow span {
  align-items: center;
  gap: 6px;
}
.onb {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 32px;
  padding: 0 8px 0 10px;
  border-radius: 999px;
  font-size: 12.5px;
  font-weight: 600;
  background: color-mix(in srgb, currentColor 12%, transparent);
  border: 1px solid color-mix(in srgb, currentColor 35%, transparent);
  cursor: pointer;
}
.onb ha-icon {
  --mdc-icon-size: 16px;
}
.onb .x {
  --mdc-icon-size: 14px;
  opacity: 0.7;
}
.onb.l {
  color: var(--warm);
}
.onb.c {
  color: var(--cool);
}
.onb.h {
  color: var(--heat);
}
.onb.ask {
  color: var(--warn);
}
